        var c = encoder.container(keyedBy: CodingKeys.self)
        try c.encode(id, forKey: .id)
        try c.encode(relativePath, forKey: .relativePath)
        try c.encode(data, forKey: .data)
        try c.encodeIfPresent(executable, forKey: .executable)
      }
    }
  }

